(function() {
    var type_impls = Object.fromEntries([["konnektoren_tui",[["<details class=\"toggle implementors-toggle\" open><summary><section id=\"impl-Clone-for-Terminal%3CB%3E\" class=\"impl\"><a href=\"#impl-Clone-for-Terminal%3CB%3E\" class=\"anchor\">§</a><h3 class=\"code-header\">impl&lt;B&gt; <a class=\"trait\" href=\"https://doc.rust-lang.org/1.96.1/core/clone/trait.Clone.html\" title=\"trait core::clone::Clone\">Clone</a> for Terminal&lt;B&gt;<div class=\"where\">where\n    B: <a class=\"trait\" href=\"https://doc.rust-lang.org/1.96.1/core/clone/trait.Clone.html\" title=\"trait core::clone::Clone\">Clone</a> + Backend,</div></h3></section></summary><div class=\"impl-items\"><details class=\"toggle method-toggle\" open><summary><section id=\"method.clone\" class=\"method trait-impl\"><a href=\"#method.clone\" class=\"anchor\">§</a><h4 class=\"code-header\">fn <a href=\"https://doc.rust-lang.org/1.96.1/core/clone/trait.Clone.html#tymethod.clone\" class=\"fn\">clone</a>(&amp;self) -&gt; Terminal&lt;B&gt;</h4></section></summary><div class='docblock'>Returns a duplicate of the value. <a href=\"https://doc.rust-lang.org/1.96.1/core/clone/trait.Clone.html#tymethod.clone\">Read more</a></div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.clone_from\" class=\"method trait-impl\"><span class=\"rightside\"><span class=\"since\" title=\"Stable since Rust version 1.0.0\">1.0.0</span> · <a class=\"src\" href=\"https://doc.rust-lang.org/1.96.1/src/core/clone.rs.html#245-247\">Source</a></span><a href=\"#method.clone_from\" class=\"anchor\">§</a><h4 class=\"code-header\">fn <a href=\"https://doc.rust-lang.org/1.96.1/core/clone/trait.Clone.html#method.clone_from\" class=\"fn\">clone_from</a>(&amp;mut self, source: &amp;Self)</h4></section></summary><div class='docblock'>Performs copy-assignment from <code>source</code>. <a href=\"https://doc.rust-lang.org/1.96.1/core/clone/trait.Clone.html#method.clone_from\">Read more</a></div></details></div></details>","Clone","konnektoren_tui::tui::Tui"],["<details class=\"toggle implementors-toggle\" open><summary><section id=\"impl-Debug-for-Terminal%3CB%3E\" class=\"impl\"><a href=\"#impl-Debug-for-Terminal%3CB%3E\" class=\"anchor\">§</a><h3 class=\"code-header\">impl&lt;B&gt; <a class=\"trait\" href=\"https://doc.rust-lang.org/1.96.1/core/fmt/trait.Debug.html\" title=\"trait core::fmt::Debug\">Debug</a> for Terminal&lt;B&gt;<div class=\"where\">where\n    B: <a class=\"trait\" href=\"https://doc.rust-lang.org/1.96.1/core/fmt/trait.Debug.html\" title=\"trait core::fmt::Debug\">Debug</a> + Backend,</div></h3></section></summary><div class=\"impl-items\"><details class=\"toggle method-toggle\" open><summary><section id=\"method.fmt\" class=\"method trait-impl\"><a href=\"#method.fmt\" class=\"anchor\">§</a><h4 class=\"code-header\">fn <a href=\"https://doc.rust-lang.org/1.96.1/core/fmt/trait.Debug.html#tymethod.fmt\" class=\"fn\">fmt</a>(&amp;self, f: &amp;mut <a class=\"struct\" href=\"https://doc.rust-lang.org/1.96.1/core/fmt/struct.Formatter.html\" title=\"struct core::fmt::Formatter\">Formatter</a>&lt;'_&gt;) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/1.96.1/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/1.96.1/std/primitive.unit.html\">()</a>, <a class=\"struct\" href=\"https://doc.rust-lang.org/1.96.1/core/fmt/struct.Error.html\" title=\"struct core::fmt::Error\">Error</a>&gt;</h4></section></summary><div class='docblock'>Formats the value using the given formatter. <a href=\"https://doc.rust-lang.org/1.96.1/core/fmt/trait.Debug.html#tymethod.fmt\">Read more</a></div></details></div></details>","Debug","konnektoren_tui::tui::Tui"],["<details class=\"toggle implementors-toggle\" open><summary><section id=\"impl-Default-for-Terminal%3CB%3E\" class=\"impl\"><a href=\"#impl-Default-for-Terminal%3CB%3E\" class=\"anchor\">§</a><h3 class=\"code-header\">impl&lt;B&gt; <a class=\"trait\" href=\"https://doc.rust-lang.org/1.96.1/core/default/trait.Default.html\" title=\"trait core::default::Default\">Default</a> for Terminal&lt;B&gt;<div class=\"where\">where\n    B: <a class=\"trait\" href=\"https://doc.rust-lang.org/1.96.1/core/default/trait.Default.html\" title=\"trait core::default::Default\">Default</a> + Backend,</div></h3></section></summary><div class=\"impl-items\"><details class=\"toggle method-toggle\" open><summary><section id=\"method.default\" class=\"method trait-impl\"><a href=\"#method.default\" class=\"anchor\">§</a><h4 class=\"code-header\">fn <a href=\"https://doc.rust-lang.org/1.96.1/core/default/trait.Default.html#tymethod.default\" class=\"fn\">default</a>() -&gt; Terminal&lt;B&gt;</h4></section></summary><div class='docblock'>Returns the “default value” for a type. <a href=\"https://doc.rust-lang.org/1.96.1/core/default/trait.Default.html#tymethod.default\">Read more</a></div></details></div></details>","Default","konnektoren_tui::tui::Tui"],["<details class=\"toggle implementors-toggle\" open><summary><section id=\"impl-Drop-for-Terminal%3CB%3E\" class=\"impl\"><a href=\"#impl-Drop-for-Terminal%3CB%3E\" class=\"anchor\">§</a><h3 class=\"code-header\">impl&lt;B&gt; <a class=\"trait\" href=\"https://doc.rust-lang.org/1.96.1/core/ops/drop/trait.Drop.html\" title=\"trait core::ops::drop::Drop\">Drop</a> for Terminal&lt;B&gt;<div class=\"where\">where\n    B: Backend,</div></h3></section></summary><div class=\"impl-items\"><details class=\"toggle method-toggle\" open><summary><section id=\"method.drop\" class=\"method trait-impl\"><a href=\"#method.drop\" class=\"anchor\">§</a><h4 class=\"code-header\">fn <a href=\"https://doc.rust-lang.org/1.96.1/core/ops/drop/trait.Drop.html#tymethod.drop\" class=\"fn\">drop</a>(&amp;mut self)</h4></section></summary><div class='docblock'>Executes the destructor for this type. <a href=\"https://doc.rust-lang.org/1.96.1/core/ops/drop/trait.Drop.html#tymethod.drop\">Read more</a></div></details></div></details>","Drop","konnektoren_tui::tui::Tui"],["<details class=\"toggle implementors-toggle\" open><summary><section id=\"impl-Hash-for-Terminal%3CB%3E\" class=\"impl\"><a href=\"#impl-Hash-for-Terminal%3CB%3E\" class=\"anchor\">§</a><h3 class=\"code-header\">impl&lt;B&gt; <a class=\"trait\" href=\"https://doc.rust-lang.org/1.96.1/core/hash/trait.Hash.html\" title=\"trait core::hash::Hash\">Hash</a> for Terminal&lt;B&gt;<div class=\"where\">where\n    B: <a class=\"trait\" href=\"https://doc.rust-lang.org/1.96.1/core/hash/trait.Hash.html\" title=\"trait core::hash::Hash\">Hash</a> + Backend,</div></h3></section></summary><div class=\"impl-items\"><details class=\"toggle method-toggle\" open><summary><section id=\"method.hash\" class=\"method trait-impl\"><a href=\"#method.hash\" class=\"anchor\">§</a><h4 class=\"code-header\">fn <a href=\"https://doc.rust-lang.org/1.96.1/core/hash/trait.Hash.html#tymethod.hash\" class=\"fn\">hash</a>&lt;__H&gt;(&amp;self, state: <a class=\"primitive\" href=\"https://doc.rust-lang.org/1.96.1/std/primitive.reference.html\">&amp;mut __H</a>)<div class=\"where\">where\n    __H: <a class=\"trait\" href=\"https://doc.rust-lang.org/1.96.1/core/hash/trait.Hasher.html\" title=\"trait core::hash::Hasher\">Hasher</a>,</div></h4></section></summary><div class='docblock'>Feeds this value into the given <a href=\"https://doc.rust-lang.org/1.96.1/core/hash/trait.Hasher.html\" title=\"trait core::hash::Hasher\"><code>Hasher</code></a>. <a href=\"https://doc.rust-lang.org/1.96.1/core/hash/trait.Hash.html#tymethod.hash\">Read more</a></div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.hash_slice\" class=\"method trait-impl\"><span class=\"rightside\"><span class=\"since\" title=\"Stable since Rust version 1.3.0\">1.3.0</span> · <a class=\"src\" href=\"https://doc.rust-lang.org/1.96.1/src/core/hash/mod.rs.html#234-236\">Source</a></span><a href=\"#method.hash_slice\" class=\"anchor\">§</a><h4 class=\"code-header\">fn <a href=\"https://doc.rust-lang.org/1.96.1/core/hash/trait.Hash.html#method.hash_slice\" class=\"fn\">hash_slice</a>&lt;H&gt;(data: &amp;[Self], state: <a class=\"primitive\" href=\"https://doc.rust-lang.org/1.96.1/std/primitive.reference.html\">&amp;mut H</a>)<div class=\"where\">where\n    H: <a class=\"trait\" href=\"https://doc.rust-lang.org/1.96.1/core/hash/trait.Hasher.html\" title=\"trait core::hash::Hasher\">Hasher</a>,\n    Self: <a class=\"trait\" href=\"https://doc.rust-lang.org/1.96.1/core/marker/trait.Sized.html\" title=\"trait core::marker::Sized\">Sized</a>,</div></h4></section></summary><div class='docblock'>Feeds a slice of this type into the given <a href=\"https://doc.rust-lang.org/1.96.1/core/hash/trait.Hasher.html\" title=\"trait core::hash::Hasher\"><code>Hasher</code></a>. <a href=\"https://doc.rust-lang.org/1.96.1/core/hash/trait.Hash.html#method.hash_slice\">Read more</a></div></details></div></details>","Hash","konnektoren_tui::tui::Tui"],["<details class=\"toggle implementors-toggle\" open><summary><section id=\"impl-PartialEq-for-Terminal%3CB%3E\" class=\"impl\"><a href=\"#impl-PartialEq-for-Terminal%3CB%3E\" class=\"anchor\">§</a><h3 class=\"code-header\">impl&lt;B&gt; <a class=\"trait\" href=\"https://doc.rust-lang.org/1.96.1/core/cmp/trait.PartialEq.html\" title=\"trait core::cmp::PartialEq\">PartialEq</a> for Terminal&lt;B&gt;<div class=\"where\">where\n    B: <a class=\"trait\" href=\"https://doc.rust-lang.org/1.96.1/core/cmp/trait.PartialEq.html\" title=\"trait core::cmp::PartialEq\">PartialEq</a> + Backend,</div></h3></section></summary><div class=\"impl-items\"><details class=\"toggle method-toggle\" open><summary><section id=\"method.eq\" class=\"method trait-impl\"><a href=\"#method.eq\" class=\"anchor\">§</a><h4 class=\"code-header\">fn <a href=\"https://doc.rust-lang.org/1.96.1/core/cmp/trait.PartialEq.html#tymethod.eq\" class=\"fn\">eq</a>(&amp;self, other: &amp;Terminal&lt;B&gt;) -&gt; <a class=\"primitive\" href=\"https://doc.rust-lang.org/1.96.1/std/primitive.bool.html\">bool</a></h4></section></summary><div class='docblock'>Tests for <code>self</code> and <code>other</code> values to be equal, and is used by <code>==</code>.</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.ne\" class=\"method trait-impl\"><span class=\"rightside\"><span class=\"since\" title=\"Stable since Rust version 1.0.0\">1.0.0</span> · <a class=\"src\" href=\"https://doc.rust-lang.org/1.96.1/src/core/cmp.rs.html#263\">Source</a></span><a href=\"#method.ne\" class=\"anchor\">§</a><h4 class=\"code-header\">fn <a href=\"https://doc.rust-lang.org/1.96.1/core/cmp/trait.PartialEq.html#method.ne\" class=\"fn\">ne</a>(&amp;self, other: <a class=\"primitive\" href=\"https://doc.rust-lang.org/1.96.1/std/primitive.reference.html\">&amp;Rhs</a>) -&gt; <a class=\"primitive\" href=\"https://doc.rust-lang.org/1.96.1/std/primitive.bool.html\">bool</a></h4></section></summary><div class='docblock'>Tests for <code>!=</code>. The default implementation is almost always sufficient,\nand should not be overridden without very good reason.</div></details></div></details>","PartialEq","konnektoren_tui::tui::Tui"],["<details class=\"toggle implementors-toggle\" open><summary><section id=\"impl-Terminal%3CB%3E\" class=\"impl\"><a href=\"#impl-Terminal%3CB%3E\" class=\"anchor\">§</a><h3 class=\"code-header\">impl&lt;B&gt; Terminal&lt;B&gt;<div class=\"where\">where\n    B: Backend,</div></h3></section></summary><div class=\"impl-items\"><details class=\"toggle method-toggle\" open><summary><section id=\"method.backend\" class=\"method\"><h4 class=\"code-header\">pub const fn <a href=\"#method.backend\" class=\"fn\">backend</a>(&amp;self) -&gt; <a class=\"primitive\" href=\"https://doc.rust-lang.org/1.96.1/std/primitive.reference.html\">&amp;B</a></h4></section></summary><div class=\"docblock\"><p>Returns a shared reference to the backend.</p>\n<p>This is primarily useful for backend-specific inspection in tests (e.g. reading\n<a href=\"crate::backend::TestBackend\"><code>TestBackend</code></a>’s buffer) or for backend-specific APIs that Ratatui does not model.</p>\n<p>Reading from the backend does not desynchronize Ratatui, but values observed here may lag\nbehind the current render callback because Ratatui does not apply a frame to the backend\nuntil the end of [<code>Terminal::draw</code>] / [<code>Terminal::try_draw</code>].</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.backend_mut\" class=\"method\"><h4 class=\"code-header\">pub const fn <a href=\"#method.backend_mut\" class=\"fn\">backend_mut</a>(&amp;mut self) -&gt; <a class=\"primitive\" href=\"https://doc.rust-lang.org/1.96.1/std/primitive.reference.html\">&amp;mut B</a></h4></section></summary><div class=\"docblock\"><p>Returns a mutable reference to the backend.</p>\n<p>This is an advanced escape hatch. Normal applications should render through\n<a href=\"crate::terminal::Terminal::draw\"><code>Terminal::draw</code></a> / <a href=\"crate::terminal::Terminal::try_draw\"><code>Terminal::try_draw</code></a> instead of mutating the backend directly.</p>\n<p>Use this when integrating with backend-specific APIs that Ratatui does not model, or when\ntests need direct control over backend state.</p>\n<p>Mutating the backend directly can desynchronize Ratatui’s internal buffers, cursor\ntracking, or viewport assumptions from what’s on-screen. If you do this, call\n<a href=\"crate::terminal::Terminal::clear\"><code>Terminal::clear</code></a> or perform a full draw pass before relying on Ratatui’s view of the\nterminal again.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.size\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.size\" class=\"fn\">size</a>(&amp;self) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/1.96.1/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;Size, &lt;B as Backend&gt;::Error&gt;</h4></section></summary><div class=\"docblock\"><p>Queries the real size of the backend.</p>\n<p>This returns the backend’s current terminal size and does not update Ratatui’s internal\nviewport bookkeeping by itself. The current renderable area depends on the configured\n<a href=\"crate::terminal::Viewport\"><code>Viewport</code></a>; use <a href=\"crate::terminal::Frame::area\"><code>Frame::area</code></a> inside <a href=\"crate::terminal::Terminal::draw\"><code>Terminal::draw</code></a> / <a href=\"crate::terminal::Terminal::try_draw\"><code>Terminal::try_draw</code></a> if you\nwant the area you should render into for the current pass.</p>\n<p>To make Ratatui observe backend size changes for fullscreen or inline viewports, see\n<a href=\"crate::terminal::Terminal::autoresize\"><code>Terminal::autoresize</code></a>.</p>\n</div></details></div></details>",0,"konnektoren_tui::tui::Tui"],["<details class=\"toggle implementors-toggle\" open><summary><section id=\"impl-Terminal%3CB%3E\" class=\"impl\"><a href=\"#impl-Terminal%3CB%3E\" class=\"anchor\">§</a><h3 class=\"code-header\">impl&lt;B&gt; Terminal&lt;B&gt;<div class=\"where\">where\n    B: Backend,</div></h3></section></summary><div class=\"impl-items\"><details class=\"toggle method-toggle\" open><summary><section id=\"method.draw\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.draw\" class=\"fn\">draw</a>&lt;F&gt;(\n    &amp;mut self,\n    render_callback: F,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/1.96.1/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;CompletedFrame&lt;'_&gt;, &lt;B as Backend&gt;::Error&gt;<div class=\"where\">where\n    F: <a class=\"trait\" href=\"https://doc.rust-lang.org/1.96.1/core/ops/function/trait.FnOnce.html\" title=\"trait core::ops::function::FnOnce\">FnOnce</a>(&amp;mut Frame&lt;'_&gt;),</div></h4></section></summary><div class=\"docblock\"><p>Draws a single frame to the terminal.</p>\n<p>Returns a [<code>CompletedFrame</code>] if successful, otherwise a backend error (<code>B::Error</code>).</p>\n<p>If the render callback passed to this method can fail, use <a href=\"Terminal::try_draw\"><code>try_draw</code></a> instead.</p>\n<p>Applications should call <code>draw</code> or <a href=\"Terminal::try_draw\"><code>try_draw</code></a> in a loop to continuously render the\nterminal. These methods are the main entry points for drawing to the terminal.</p>\n<p>The [<code>Frame</code>] passed to the render callback represents the currently configured\n<a href=\"crate::terminal::Viewport\"><code>Viewport</code></a> (see <a href=\"crate::terminal::Frame::area\"><code>Frame::area</code></a> and [<code>Terminal::with_options</code>]).</p>\n<p>Build layout relative to the <a href=\"crate::layout::Rect\"><code>Rect</code></a> returned by <a href=\"crate::terminal::Frame::area\"><code>Frame::area</code></a> rather than assuming the\norigin is <code>(0, 0)</code>, so the same rendering code works for fixed and inline viewports.</p>\n<p>This method will:</p>\n<ul>\n<li>call [<code>Terminal::autoresize</code>] if necessary</li>\n<li>call the render callback, passing it a [<code>Frame</code>] reference to render to</li>\n<li>call [<code>Terminal::flush</code>] to apply the current buffer diff to the backend</li>\n<li>show/hide the cursor based on [<code>Frame::set_cursor_position</code>]</li>\n<li>call [<code>Terminal::swap_buffers</code>] to prepare for the next render pass</li>\n<li>call <a href=\"crate::backend::Backend::flush\"><code>Backend::flush</code></a> to flush any buffered backend output</li>\n<li>return a [<code>CompletedFrame</code>] with the current buffer and the area used for rendering</li>\n</ul>\n<p>If any backend step fails, the error is returned immediately and later steps in the render\npass are skipped.</p>\n<p>The [<code>CompletedFrame</code>] returned by this method can be useful for debugging or testing\npurposes, but it is often not used in regular applications.</p>\n<p>The render callback should fully render the entire frame when called, including areas that\nare unchanged from the previous frame. This is because each frame is compared to the\nprevious frame to determine what has changed, and only the changes are written to the\nterminal. If the render callback does not fully render the frame, the terminal will not be\nin a consistent state.</p>\n<h5 id=\"examples\"><a class=\"doc-anchor\" href=\"#examples\">§</a>Examples</h5>\n<div class=\"example-wrap\"><pre class=\"rust rust-example-rendered\"><code><span class=\"kw\">use </span>ratatui::backend::TestBackend;\n<span class=\"kw\">use </span>ratatui::layout::Position;\n<span class=\"kw\">use </span>ratatui::{Frame, Terminal};\n\n<span class=\"kw\">let </span>backend = TestBackend::new(<span class=\"number\">10</span>, <span class=\"number\">10</span>);\n<span class=\"kw\">let </span><span class=\"kw-2\">mut </span>terminal = Terminal::new(backend)<span class=\"question-mark\">?</span>;\n\n<span class=\"comment\">// With a closure.\n</span>terminal.draw(|frame| {\n    <span class=\"kw\">let </span>area = frame.area();\n    frame.render_widget(<span class=\"string\">\"Hello World!\"</span>, area);\n    frame.set_cursor_position(Position { x: <span class=\"number\">0</span>, y: <span class=\"number\">0 </span>});\n})<span class=\"question-mark\">?</span>;\n\n<span class=\"comment\">// Or with a function.\n</span>terminal.draw(render)<span class=\"question-mark\">?</span>;\n\n<span class=\"kw\">fn </span>render(frame: <span class=\"kw-2\">&amp;mut </span>Frame&lt;<span class=\"lifetime\">'_</span>&gt;) {\n    frame.render_widget(<span class=\"string\">\"Hello World!\"</span>, frame.area());\n}</code></pre></div></div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.try_draw\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.try_draw\" class=\"fn\">try_draw</a>&lt;F, E&gt;(\n    &amp;mut self,\n    render_callback: F,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/1.96.1/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;CompletedFrame&lt;'_&gt;, &lt;B as Backend&gt;::Error&gt;<div class=\"where\">where\n    F: <a class=\"trait\" href=\"https://doc.rust-lang.org/1.96.1/core/ops/function/trait.FnOnce.html\" title=\"trait core::ops::function::FnOnce\">FnOnce</a>(&amp;mut Frame&lt;'_&gt;) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/1.96.1/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/1.96.1/std/primitive.unit.html\">()</a>, E&gt;,\n    E: <a class=\"trait\" href=\"https://doc.rust-lang.org/1.96.1/core/convert/trait.Into.html\" title=\"trait core::convert::Into\">Into</a>&lt;&lt;B as Backend&gt;::Error&gt;,</div></h4></section></summary><div class=\"docblock\"><p>Tries to draw a single frame to the terminal.</p>\n<p>Returns <a href=\"https://doc.rust-lang.org/1.96.1/core/result/enum.Result.html#variant.Ok\" title=\"variant core::result::Result::Ok\"><code>Result::Ok</code></a> containing a [<code>CompletedFrame</code>] if successful, otherwise\n<a href=\"https://doc.rust-lang.org/1.96.1/core/result/enum.Result.html#variant.Err\" title=\"variant core::result::Result::Err\"><code>Result::Err</code></a> containing the backend error (<code>B::Error</code>) that caused the failure.</p>\n<p>This is the equivalent of [<code>Terminal::draw</code>] but the render callback is a function or\nclosure that returns a <code>Result</code> instead of nothing.</p>\n<p>Applications should call <code>try_draw</code> or <a href=\"Terminal::draw\"><code>draw</code></a> in a loop to continuously render the\nterminal. These methods are the main entry points for drawing to the terminal.</p>\n<p>The [<code>Frame</code>] passed to the render callback represents the currently configured\n<a href=\"crate::terminal::Viewport\"><code>Viewport</code></a> (see <a href=\"crate::terminal::Frame::area\"><code>Frame::area</code></a> and [<code>Terminal::with_options</code>]).</p>\n<p>Build layout relative to the <a href=\"crate::layout::Rect\"><code>Rect</code></a> returned by <a href=\"crate::terminal::Frame::area\"><code>Frame::area</code></a> rather than assuming the\norigin is <code>(0, 0)</code>, so the same rendering code works for fixed and inline viewports.</p>\n<p>This method will:</p>\n<ul>\n<li>call [<code>Terminal::autoresize</code>] if necessary</li>\n<li>call the render callback, passing it a [<code>Frame</code>] reference to render to</li>\n<li>call [<code>Terminal::flush</code>] to apply the current buffer diff to the backend</li>\n<li>show/hide the cursor based on [<code>Frame::set_cursor_position</code>]</li>\n<li>call [<code>Terminal::swap_buffers</code>] to prepare for the next render pass</li>\n<li>call <a href=\"crate::backend::Backend::flush\"><code>Backend::flush</code></a> to flush any buffered backend output</li>\n<li>return a [<code>CompletedFrame</code>] with the current buffer and the area used for rendering</li>\n</ul>\n<p>If the render callback returns an error, Ratatui leaves the backend, buffers, cursor state,\nand frame count unchanged.</p>\n<p>The render callback passed to <code>try_draw</code> can return any <a href=\"https://doc.rust-lang.org/1.96.1/core/result/enum.Result.html\" title=\"enum core::result::Result\"><code>Result</code></a> with an error type that\ncan be converted into <code>B::Error</code> using the <a href=\"https://doc.rust-lang.org/1.96.1/core/convert/trait.Into.html\" title=\"trait core::convert::Into\"><code>Into</code></a> trait. This makes it possible to use the\n<code>?</code> operator to propagate errors that occur during rendering. If the render callback returns\nan error, the error will be returned from <code>try_draw</code> and the terminal will not be updated.</p>\n<p>The [<code>CompletedFrame</code>] returned by this method can be useful for debugging or testing\npurposes, but it is often not used in regular applications.</p>\n<p>The render callback should fully render the entire frame when called, including areas that\nare unchanged from the previous frame. This is because each frame is compared to the\nprevious frame to determine what has changed, and only the changes are written to the\nterminal. If the render function does not fully render the frame, the terminal will not be\nin a consistent state.</p>\n<h5 id=\"examples-1\"><a class=\"doc-anchor\" href=\"#examples-1\">§</a>Examples</h5>\n<div class=\"example-wrap\"><pre class=\"rust rust-example-rendered\"><code><span class=\"kw\">use </span>std::io;\n\n<span class=\"kw\">use </span>ratatui::backend::CrosstermBackend;\n<span class=\"kw\">use </span>ratatui::layout::Position;\n<span class=\"kw\">use </span>ratatui::{Frame, Terminal};\n\n<span class=\"kw\">let </span>backend = CrosstermBackend::new(std::io::stdout());\n<span class=\"kw\">let </span><span class=\"kw-2\">mut </span>terminal = Terminal::new(backend)<span class=\"question-mark\">?</span>;\n\n<span class=\"comment\">// With a closure that returns `Result`.\n</span>terminal.try_draw(|frame| -&gt; io::Result&lt;()&gt; {\n    <span class=\"kw\">let </span>_value: u8 = <span class=\"string\">\"42\"</span>.parse().map_err(io::Error::other)<span class=\"question-mark\">?</span>;\n    <span class=\"kw\">let </span>area = frame.area();\n    frame.render_widget(<span class=\"string\">\"Hello World!\"</span>, area);\n    frame.set_cursor_position(Position { x: <span class=\"number\">0</span>, y: <span class=\"number\">0 </span>});\n    <span class=\"prelude-val\">Ok</span>(())\n})<span class=\"question-mark\">?</span>;\n\n<span class=\"comment\">// Or with a function.\n</span>terminal.try_draw(render)<span class=\"question-mark\">?</span>;\n\n<span class=\"kw\">fn </span>render(frame: <span class=\"kw-2\">&amp;mut </span>Frame&lt;<span class=\"lifetime\">'_</span>&gt;) -&gt; io::Result&lt;()&gt; {\n    frame.render_widget(<span class=\"string\">\"Hello World!\"</span>, frame.area());\n    <span class=\"prelude-val\">Ok</span>(())\n}</code></pre></div></div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.apply_buffer\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.apply_buffer\" class=\"fn\">apply_buffer</a>(\n    &amp;mut self,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/1.96.1/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;CompletedFrame&lt;'_&gt;, &lt;B as Backend&gt;::Error&gt;</h4></section></summary><div class=\"docblock\"><p>A low-level function that applies and flushes the current buffer to the backend.</p>\n<p>This calls [<code>Terminal::apply_buffer_with_cursor</code>] with <a href=\"https://doc.rust-lang.org/1.96.1/core/option/enum.Option.html#variant.None\" title=\"variant core::option::Option::None\"><code>None</code></a>, which hides the cursor.</p>\n<h5 id=\"examples-2\"><a class=\"doc-anchor\" href=\"#examples-2\">§</a>Examples</h5>\n<div class=\"example-wrap\"><pre class=\"rust rust-example-rendered\"><code><span class=\"kw\">use </span>std::io;\n\n<span class=\"kw\">use </span>ratatui::Terminal;\n<span class=\"kw\">use </span>ratatui::backend::CrosstermBackend;\n<span class=\"kw\">use </span>ratatui::buffer::Buffer;\n<span class=\"kw\">use </span>ratatui::widgets::Widget;\n\n<span class=\"kw\">let </span>backend = CrosstermBackend::new(io::stdout());\n<span class=\"kw\">let </span><span class=\"kw-2\">mut </span>terminal = Terminal::new(backend)<span class=\"question-mark\">?</span>;\n\nterminal.autoresize()<span class=\"question-mark\">?</span>;\n\n<span class=\"kw\">let </span><span class=\"kw-2\">mut </span>custom_buffer = Buffer::default();\ncustom_buffer.resize(terminal.get_frame().area());\ncustom_buffer.reset();\n\n<span class=\"string\">\"Hello World!\"</span>.render(custom_buffer.area, <span class=\"kw-2\">&amp;mut </span>custom_buffer);\n\nterminal.current_buffer_mut().merge(<span class=\"kw-2\">&amp;</span>custom_buffer);\nterminal.apply_buffer()<span class=\"question-mark\">?</span>;</code></pre></div></div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.apply_buffer_with_cursor\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.apply_buffer_with_cursor\" class=\"fn\">apply_buffer_with_cursor</a>(\n    &amp;mut self,\n    cursor_position: <a class=\"enum\" href=\"https://doc.rust-lang.org/1.96.1/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;Position&gt;,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/1.96.1/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;CompletedFrame&lt;'_&gt;, &lt;B as Backend&gt;::Error&gt;</h4></section></summary><div class=\"docblock\"><p>A low-level function that applies and flushes the current buffer to the backend and\nre-positions the cursor. This function is useful if you need to manage your own custom\ndraw lifecycle and buffer.</p>\n<p>Returns <a href=\"https://doc.rust-lang.org/1.96.1/core/result/enum.Result.html#variant.Ok\" title=\"variant core::result::Result::Ok\"><code>Result::Ok</code></a> containing a [<code>CompletedFrame</code>] if successful, otherwise\n<a href=\"https://doc.rust-lang.org/1.96.1/core/result/enum.Result.html#variant.Err\" title=\"variant core::result::Result::Err\"><code>Result::Err</code></a> containing the backend error (<code>B::Error</code>) that caused the failure.</p>\n<p>This method will:</p>\n<ul>\n<li>show/hide the cursor based on <code>cursor_position</code> (<a href=\"https://doc.rust-lang.org/1.96.1/core/option/enum.Option.html#variant.None\" title=\"variant core::option::Option::None\"><code>None</code></a> will hide the cursor)</li>\n<li>call [<code>Terminal::swap_buffers</code>] to prepare for the next render pass</li>\n<li>call [<code>Backend::flush</code>] to flush any buffered backend output</li>\n<li>return a [<code>CompletedFrame</code>] with the current buffer and the area used for rendering</li>\n</ul>\n<p>The [<code>CompletedFrame</code>] returned by this method can be useful for debugging or testing\npurposes, but it is often not used in regular applications.</p>\n<h5 id=\"examples-3\"><a class=\"doc-anchor\" href=\"#examples-3\">§</a>Examples</h5>\n<div class=\"example-wrap\"><pre class=\"rust rust-example-rendered\"><code><span class=\"kw\">use </span>std::io;\n\n<span class=\"kw\">use </span>ratatui::Terminal;\n<span class=\"kw\">use </span>ratatui::backend::CrosstermBackend;\n<span class=\"kw\">use </span>ratatui::buffer::Buffer;\n<span class=\"kw\">use </span>ratatui::widgets::Widget;\n\n<span class=\"kw\">let </span>backend = CrosstermBackend::new(io::stdout());\n<span class=\"kw\">let </span><span class=\"kw-2\">mut </span>terminal = Terminal::new(backend)<span class=\"question-mark\">?</span>;\n\nterminal.autoresize()<span class=\"question-mark\">?</span>;\n\n<span class=\"kw\">let </span><span class=\"kw-2\">mut </span>custom_buffer = Buffer::default();\ncustom_buffer.resize(terminal.get_frame().area());\ncustom_buffer.reset();\n\n<span class=\"string\">\"Hello World!\"</span>.render(custom_buffer.area, <span class=\"kw-2\">&amp;mut </span>custom_buffer);\n\nterminal.current_buffer_mut().merge(<span class=\"kw-2\">&amp;</span>custom_buffer);\nterminal.apply_buffer_with_cursor(<span class=\"prelude-val\">None</span>)<span class=\"question-mark\">?</span>;</code></pre></div></div></details></div></details>",0,"konnektoren_tui::tui::Tui"],["<details class=\"toggle implementors-toggle\" open><summary><section id=\"impl-Terminal%3CB%3E\" class=\"impl\"><a href=\"#impl-Terminal%3CB%3E\" class=\"anchor\">§</a><h3 class=\"code-header\">impl&lt;B&gt; Terminal&lt;B&gt;<div class=\"where\">where\n    B: Backend,</div></h3></section></summary><div class=\"impl-items\"><details class=\"toggle method-toggle\" open><summary><section id=\"method.get_frame\" class=\"method\"><h4 class=\"code-header\">pub const fn <a href=\"#method.get_frame\" class=\"fn\">get_frame</a>(&amp;mut self) -&gt; Frame&lt;'_&gt;</h4></section></summary><div class=\"docblock\"><p>Returns a [<code>Frame</code>] for manual rendering.</p>\n<p>Most applications should render via [<code>Terminal::draw</code>] / [<code>Terminal::try_draw</code>]. This is an\nescape hatch that exposes the frame construction step used by [<code>Terminal::try_draw</code>] so\ntests and advanced callers can render without running the full draw pipeline.</p>\n<p>This is primarily useful for tests, backend adapters, and specialized integrations that\nintentionally manage presentation themselves.</p>\n<p>Unlike <code>draw</code> / <code>try_draw</code>, this does not call [<code>Terminal::autoresize</code>], does not write\nupdates to the backend, and does not apply any cursor changes. After rendering, you\ntypically call [<code>Terminal::flush</code>], [<code>Terminal::swap_buffers</code>], and <a href=\"crate::backend::Backend::flush\"><code>Backend::flush</code></a>.</p>\n<p>For the full render-pass behavior that also handles resizing, cursor updates, buffer\nswapping, and backend flushing, see [<code>Terminal::draw</code>] and [<code>Terminal::try_draw</code>].</p>\n<p>The returned <code>Frame</code> mutably borrows the current buffer, so it must be dropped before you\ncan call methods like [<code>Terminal::flush</code>]. The example below uses a scope to make that\nexplicit.</p>\n<h5 id=\"example\"><a class=\"doc-anchor\" href=\"#example\">§</a>Example</h5>\n<div class=\"example-wrap\"><pre class=\"rust rust-example-rendered\"><code><span class=\"kw\">use </span>ratatui::Terminal;\n<span class=\"kw\">use </span>ratatui::backend::{Backend, TestBackend};\n\n<span class=\"kw\">let </span>backend = TestBackend::new(<span class=\"number\">30</span>, <span class=\"number\">5</span>);\n<span class=\"kw\">let </span><span class=\"kw-2\">mut </span>terminal = Terminal::new(backend)<span class=\"question-mark\">?</span>;\n{\n    <span class=\"kw\">let </span><span class=\"kw-2\">mut </span>frame = terminal.get_frame();\n    frame.render_widget(<span class=\"string\">\"Hello\"</span>, frame.area());\n}\n<span class=\"comment\">// When not using `draw`, present the buffer manually:\n</span>terminal.flush()<span class=\"question-mark\">?</span>;\nterminal.swap_buffers();\nterminal.backend_mut().flush()<span class=\"question-mark\">?</span>;</code></pre></div></div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.current_buffer_mut\" class=\"method\"><h4 class=\"code-header\">pub const fn <a href=\"#method.current_buffer_mut\" class=\"fn\">current_buffer_mut</a>(&amp;mut self) -&gt; &amp;mut Buffer</h4></section></summary><div class=\"docblock\"><p>Gets the current buffer as a mutable reference.</p>\n<p>This is the buffer that the next [<code>Frame</code>] will render into (see [<code>Terminal::get_frame</code>]).\nThis is a low-level escape hatch; normal applications should render inside\n[<code>Terminal::draw</code>] and access the buffer through widgets, or through [<code>Frame::buffer_mut</code>]\nwhen they intentionally need direct cell access during a render pass.</p>\n<p>Mutating this buffer does not update the backend immediately. The changes become visible\nonly after a later [<code>Terminal::flush</code>] or full draw pass applies the diff. Because this\nbypasses the usual render callback structure, it is mainly useful for tests and specialized\nintegrations that intentionally manage presentation themselves.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.flush\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.flush\" class=\"fn\">flush</a>(&amp;mut self) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/1.96.1/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/1.96.1/std/primitive.unit.html\">()</a>, &lt;B as Backend&gt;::Error&gt;</h4></section></summary><div class=\"docblock\"><p>Applies the current buffer diff to the backend’s active display surface.</p>\n<p>This compares the current buffer with the previous buffer and passes only the changed cells\nto [<code>Backend::draw</code>]. It is one of the building blocks used by [<code>Terminal::draw</code>] /\n[<code>Terminal::try_draw</code>].</p>\n<p>This method does not swap buffers, does not update cursor visibility or position, and does\nnot call <a href=\"crate::backend::Backend::flush\"><code>Backend::flush</code></a>. See [<code>Terminal::swap_buffers</code>] and <a href=\"crate::backend::Backend::flush\"><code>Backend::flush</code></a>.</p>\n<p><code>Terminal::flush</code> only reasons about Ratatui’s internal buffers. It does not know whether\nthe backend’s display surface changed since the last render pass. For example, if you leave\nthe alternate screen and then call <code>Terminal::flush</code>, Ratatui may replay a diff that was\ncomputed for the alternate screen onto the main screen. In normal applications, prefer\n[<code>Terminal::draw</code>] / [<code>Terminal::try_draw</code>] unless you are intentionally managing the whole\nrender pipeline yourself.</p>\n<p>Implementation note: when there are updates, Ratatui records the position of the last\nupdated cell as the “last known cursor position”. Inline viewports use this to preserve the\ncursor’s relative position within the viewport across resizes.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.swap_buffers\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.swap_buffers\" class=\"fn\">swap_buffers</a>(&amp;mut self)</h4></section></summary><div class=\"docblock\"><p>Clears the inactive buffer and swaps it with the current buffer.</p>\n<p>This is part of the standard rendering flow (see [<code>Terminal::try_draw</code>]). If you render\nmanually using [<code>Terminal::get_frame</code>] and [<code>Terminal::flush</code>], call this immediately\nafterward so the next flush can compute diffs against the correct “previous” buffer.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.clear\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.clear\" class=\"fn\">clear</a>(&amp;mut self) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/1.96.1/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/1.96.1/std/primitive.unit.html\">()</a>, &lt;B as Backend&gt;::Error&gt;</h4></section></summary><div class=\"docblock\"><p>Clear the terminal and force a full redraw on the next draw call.</p>\n<p>What gets cleared depends on the active [<code>Viewport</code>]:</p>\n<ul>\n<li>[<code>Viewport::Fullscreen</code>]: clears the entire terminal.</li>\n<li>[<code>Viewport::Fixed</code>]: clears only the viewport region.</li>\n<li>[<code>Viewport::Inline</code>]: clears after the viewport’s origin, leaving any content above the\nviewport untouched.</li>\n</ul>\n<p>Current behavior: for [<code>Viewport::Inline</code>], clearing runs from the viewport origin through\nthe end of the visible display area, not just the viewport’s rectangle. This is an\nimplementation detail rather than a contract; do not rely on it.</p>\n<p>This preserves the backend’s current cursor position.</p>\n<p>This also resets the “previous” buffer so the next [<code>Terminal::flush</code>] redraws the full\nviewport.</p>\n<p>Implementation note: this uses [<code>ClearType::AfterCursor</code>] starting at the viewport origin.</p>\n</div></details></div></details>",0,"konnektoren_tui::tui::Tui"],["<details class=\"toggle implementors-toggle\" open><summary><section id=\"impl-Terminal%3CB%3E\" class=\"impl\"><a href=\"#impl-Terminal%3CB%3E\" class=\"anchor\">§</a><h3 class=\"code-header\">impl&lt;B&gt; Terminal&lt;B&gt;<div class=\"where\">where\n    B: Backend,</div></h3></section></summary><div class=\"impl-items\"><details class=\"toggle method-toggle\" open><summary><section id=\"method.hide_cursor\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.hide_cursor\" class=\"fn\">hide_cursor</a>(&amp;mut self) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/1.96.1/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/1.96.1/std/primitive.unit.html\">()</a>, &lt;B as Backend&gt;::Error&gt;</h4></section></summary><div class=\"docblock\"><p>Hides the cursor.</p>\n<p>When using <a href=\"crate::terminal::Terminal::draw\"><code>Terminal::draw</code></a> / <a href=\"crate::terminal::Terminal::try_draw\"><code>Terminal::try_draw</code></a>, prefer controlling the cursor with\n<a href=\"crate::terminal::Frame::set_cursor_position\"><code>Frame::set_cursor_position</code></a>. A later successful <a href=\"crate::terminal::Terminal::draw\"><code>Terminal::draw</code></a> /\n<a href=\"crate::terminal::Terminal::try_draw\"><code>Terminal::try_draw</code></a> call may overwrite this change.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.show_cursor\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.show_cursor\" class=\"fn\">show_cursor</a>(&amp;mut self) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/1.96.1/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/1.96.1/std/primitive.unit.html\">()</a>, &lt;B as Backend&gt;::Error&gt;</h4></section></summary><div class=\"docblock\"><p>Shows the cursor.</p>\n<p>When using <a href=\"crate::terminal::Terminal::draw\"><code>Terminal::draw</code></a> / <a href=\"crate::terminal::Terminal::try_draw\"><code>Terminal::try_draw</code></a>, prefer controlling the cursor with\n<a href=\"crate::terminal::Frame::set_cursor_position\"><code>Frame::set_cursor_position</code></a>. A later successful <a href=\"crate::terminal::Terminal::draw\"><code>Terminal::draw</code></a> /\n<a href=\"crate::terminal::Terminal::try_draw\"><code>Terminal::try_draw</code></a> call may overwrite this change.</p>\n</div></details><details class=\"toggle method-toggle deprecated\" open><summary><section id=\"method.get_cursor\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.get_cursor\" class=\"fn\">get_cursor</a>(&amp;mut self) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/1.96.1/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;(<a class=\"primitive\" href=\"https://doc.rust-lang.org/1.96.1/std/primitive.u16.html\">u16</a>, <a class=\"primitive\" href=\"https://doc.rust-lang.org/1.96.1/std/primitive.u16.html\">u16</a>), &lt;B as Backend&gt;::Error&gt;</h4></section><span class=\"item-info\"><div class=\"stab deprecated\"><span class=\"emoji\">👎</span><span>Deprecated: <p>use <code>get_cursor_position()</code> instead which returns <code>Result&lt;Position&gt;</code></p>\n</span></div></span></summary><div class=\"docblock\"><p>Gets the current cursor position.</p>\n<p>This queries the backend for the current cursor position and returns it as an <code>(x, y)</code>\ntuple.</p>\n</div></details><details class=\"toggle method-toggle deprecated\" open><summary><section id=\"method.set_cursor\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.set_cursor\" class=\"fn\">set_cursor</a>(\n    &amp;mut self,\n    x: <a class=\"primitive\" href=\"https://doc.rust-lang.org/1.96.1/std/primitive.u16.html\">u16</a>,\n    y: <a class=\"primitive\" href=\"https://doc.rust-lang.org/1.96.1/std/primitive.u16.html\">u16</a>,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/1.96.1/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/1.96.1/std/primitive.unit.html\">()</a>, &lt;B as Backend&gt;::Error&gt;</h4></section><span class=\"item-info\"><div class=\"stab deprecated\"><span class=\"emoji\">👎</span><span>Deprecated: <p>use <code>set_cursor_position((x, y))</code> instead which takes <code>impl Into&lt;Position&gt;</code></p>\n</span></div></span></summary><div class=\"docblock\"><p>Sets the cursor position.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.get_cursor_position\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.get_cursor_position\" class=\"fn\">get_cursor_position</a>(&amp;mut self) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/1.96.1/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;Position, &lt;B as Backend&gt;::Error&gt;</h4></section></summary><div class=\"docblock\"><p>Gets the current cursor position.</p>\n<p>This queries the backend for the current cursor position. It is not limited to Ratatui’s\nlast render pass, so direct backend mutations may also affect the returned value.</p>\n<p>When using <a href=\"crate::terminal::Terminal::draw\"><code>Terminal::draw</code></a> / <a href=\"crate::terminal::Terminal::try_draw\"><code>Terminal::try_draw</code></a>, prefer controlling the cursor with\n<a href=\"crate::terminal::Frame::set_cursor_position\"><code>Frame::set_cursor_position</code></a>. For direct control, see [<code>Terminal::set_cursor_position</code>].</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.set_cursor_position\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.set_cursor_position\" class=\"fn\">set_cursor_position</a>&lt;P&gt;(\n    &amp;mut self,\n    position: P,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/1.96.1/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/1.96.1/std/primitive.unit.html\">()</a>, &lt;B as Backend&gt;::Error&gt;<div class=\"where\">where\n    P: <a class=\"trait\" href=\"https://doc.rust-lang.org/1.96.1/core/convert/trait.Into.html\" title=\"trait core::convert::Into\">Into</a>&lt;Position&gt;,</div></h4></section></summary><div class=\"docblock\"><p>Sets the cursor position.</p>\n<p>This updates the backend cursor and Ratatui’s internal cursor tracking. Inline viewports\nuse that tracking when recomputing the viewport on resize.</p>\n<p>When using <a href=\"crate::terminal::Terminal::draw\"><code>Terminal::draw</code></a> / <a href=\"crate::terminal::Terminal::try_draw\"><code>Terminal::try_draw</code></a>, consider using\n<a href=\"crate::terminal::Frame::set_cursor_position\"><code>Frame::set_cursor_position</code></a> instead so the cursor is updated as part of the normal\nrendering flow. A later successful\n<a href=\"crate::terminal::Terminal::draw\"><code>Terminal::draw</code></a> / <a href=\"crate::terminal::Terminal::try_draw\"><code>Terminal::try_draw</code></a> call may overwrite a direct cursor move.</p>\n</div></details></div></details>",0,"konnektoren_tui::tui::Tui"],["<details class=\"toggle implementors-toggle\" open><summary><section id=\"impl-Terminal%3CB%3E\" class=\"impl\"><a href=\"#impl-Terminal%3CB%3E\" class=\"anchor\">§</a><h3 class=\"code-header\">impl&lt;B&gt; Terminal&lt;B&gt;<div class=\"where\">where\n    B: Backend,</div></h3></section></summary><div class=\"impl-items\"><details class=\"toggle method-toggle\" open><summary><section id=\"method.insert_before\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.insert_before\" class=\"fn\">insert_before</a>&lt;F&gt;(\n    &amp;mut self,\n    height: <a class=\"primitive\" href=\"https://doc.rust-lang.org/1.96.1/std/primitive.u16.html\">u16</a>,\n    draw_fn: F,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/1.96.1/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/1.96.1/std/primitive.unit.html\">()</a>, &lt;B as Backend&gt;::Error&gt;<div class=\"where\">where\n    F: <a class=\"trait\" href=\"https://doc.rust-lang.org/1.96.1/core/ops/function/trait.FnOnce.html\" title=\"trait core::ops::function::FnOnce\">FnOnce</a>(&amp;mut Buffer),</div></h4></section></summary><div class=\"docblock\"><p>Insert some content before the current inline viewport. This has no effect when the\nviewport is not inline.</p>\n<p>This is intended for inline UIs that want to print output (e.g. logs or status messages)\nabove the UI without breaking it. See [<code>Viewport::Inline</code>] for how inline viewports are\nanchored.</p>\n<p>The <code>draw_fn</code> closure will be called to draw into a writable <code>Buffer</code> that is <code>height</code>\nlines tall. The content of that <code>Buffer</code> will then be inserted before the viewport.</p>\n<p>When Ratatui is built with the <code>scrolling-regions</code> feature, this can be done without\nclearing and redrawing the viewport. Without <code>scrolling-regions</code>, Ratatui falls back to a\nmore portable approach and clears the viewport so the next [<code>Terminal::draw</code>] /\n[<code>Terminal::try_draw</code>] repaints it.</p>\n<p>If the viewport isn’t yet at the bottom of the screen, inserted lines will push it towards\nthe bottom. Once the viewport is at the bottom of the screen, inserted lines will scroll\nthe area of the screen above the viewport upwards.</p>\n<p>Before:</p>\n<div class=\"example-wrap\"><pre class=\"language-text\"><code>+---------------------+\n| pre-existing line 1 |\n| pre-existing line 2 |\n+---------------------+\n|       viewport      |\n+---------------------+\n|                     |\n|                     |\n+---------------------+</code></pre></div>\n<p>After inserting 2 lines:</p>\n<div class=\"example-wrap\"><pre class=\"language-text\"><code>+---------------------+\n| pre-existing line 1 |\n| pre-existing line 2 |\n|   inserted line 1   |\n|   inserted line 2   |\n+---------------------+\n|       viewport      |\n+---------------------+\n+---------------------+</code></pre></div>\n<p>After inserting 2 more lines:</p>\n<div class=\"example-wrap\"><pre class=\"language-text\"><code>+---------------------+\n| pre-existing line 2 |\n|   inserted line 1   |\n|   inserted line 2   |\n|   inserted line 3   |\n|   inserted line 4   |\n+---------------------+\n|       viewport      |\n+---------------------+</code></pre></div>\n<p>If more lines are inserted than there is space on the screen, then the top lines will go\ndirectly into the terminal’s scrollback buffer. At the limit, if the viewport takes up the\nwhole screen, all lines will be inserted directly into the scrollback buffer.</p>\n<h5 id=\"examples\"><a class=\"doc-anchor\" href=\"#examples\">§</a>Examples</h5><h6 id=\"insert-a-single-line-before-the-current-viewport\"><a class=\"doc-anchor\" href=\"#insert-a-single-line-before-the-current-viewport\">§</a>Insert a single line before the current viewport</h6>\n<div class=\"example-wrap\"><pre class=\"rust rust-example-rendered\"><code><span class=\"kw\">use </span>ratatui::backend::{Backend, TestBackend};\n<span class=\"kw\">use </span>ratatui::layout::Position;\n<span class=\"kw\">use </span>ratatui::style::{Color, Style};\n<span class=\"kw\">use </span>ratatui::text::{Line, Span};\n<span class=\"kw\">use </span>ratatui::widgets::Widget;\n<span class=\"kw\">use </span>ratatui::{Terminal, TerminalOptions, Viewport};\n\n<span class=\"kw\">let </span><span class=\"kw-2\">mut </span>backend = TestBackend::new(<span class=\"number\">10</span>, <span class=\"number\">10</span>);\n<span class=\"comment\">// Simulate existing output above the inline UI.\n</span>backend.set_cursor_position(Position::new(<span class=\"number\">0</span>, <span class=\"number\">3</span>))<span class=\"question-mark\">?</span>;\n<span class=\"kw\">let </span><span class=\"kw-2\">mut </span>terminal = Terminal::with_options(\n    backend,\n    TerminalOptions {\n        viewport: Viewport::Inline(<span class=\"number\">4</span>),\n    },\n)<span class=\"question-mark\">?</span>;\n\nterminal.insert_before(<span class=\"number\">1</span>, |buf| {\n    Line::from(<span class=\"macro\">vec!</span>[\n        Span::raw(<span class=\"string\">\"This line will be added \"</span>),\n        Span::styled(<span class=\"string\">\"before\"</span>, Style::default().fg(Color::Blue)),\n        Span::raw(<span class=\"string\">\" the current viewport\"</span>),\n    ])\n    .render(buf.area, buf);\n})<span class=\"question-mark\">?</span>;</code></pre></div></div></details></div></details>",0,"konnektoren_tui::tui::Tui"],["<details class=\"toggle implementors-toggle\" open><summary><section id=\"impl-Terminal%3CB%3E\" class=\"impl\"><a href=\"#impl-Terminal%3CB%3E\" class=\"anchor\">§</a><h3 class=\"code-header\">impl&lt;B&gt; Terminal&lt;B&gt;<div class=\"where\">where\n    B: Backend,</div></h3></section></summary><div class=\"impl-items\"><details class=\"toggle method-toggle\" open><summary><section id=\"method.new\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.new\" class=\"fn\">new</a>(backend: B) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/1.96.1/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;Terminal&lt;B&gt;, &lt;B as Backend&gt;::Error&gt;</h4></section></summary><div class=\"docblock\"><p>Creates a new [<code>Terminal</code>] with the given [<code>Backend</code>] with a full screen viewport.</p>\n<p>This is a convenience for [<code>Terminal::with_options</code>] with [<code>Viewport::Fullscreen</code>].\nRatatui initializes two empty buffers sized to the backend’s current screen area and treats\nfuture backend size changes as redraw-triggering resizes during render passes.</p>\n<p>After creating a terminal, call [<code>Terminal::draw</code>] (or [<code>Terminal::try_draw</code>]) in a loop to\nrender your UI.</p>\n<p>Note that unlike <a href=\"https://docs.rs/ratatui/latest/ratatui/fn.init.html\"><code>ratatui::init</code></a>, this does not install a panic hook, so it is\nrecommended to do that manually when using this function, otherwise any panic messages will\nbe printed to the alternate screen and the terminal may be left in an unusable state.</p>\n<p>See <a href=\"https://ratatui.rs/recipes/apps/panic-hooks/\">how to set up panic hooks</a> and\n<a href=\"https://ratatui.rs/recipes/apps/better-panic/\"><code>better-panic</code> example</a> for more\ninformation.</p>\n<h5 id=\"example\"><a class=\"doc-anchor\" href=\"#example\">§</a>Example</h5>\n<div class=\"example-wrap\"><pre class=\"rust rust-example-rendered\"><code><span class=\"kw\">use </span>std::io::stdout;\n\n<span class=\"kw\">use </span>ratatui::Terminal;\n<span class=\"kw\">use </span>ratatui::backend::CrosstermBackend;\n\n<span class=\"kw\">let </span>backend = CrosstermBackend::new(stdout());\n<span class=\"kw\">let </span>_terminal = Terminal::new(backend)<span class=\"question-mark\">?</span>;\n\n<span class=\"comment\">// Optionally set up a panic hook to restore the terminal on panic.\n</span><span class=\"kw\">let </span>old_hook = std::panic::take_hook();\nstd::panic::set_hook(Box::new(<span class=\"kw\">move </span>|info| {\n    ratatui::restore();\n    old_hook(info);\n}));</code></pre></div></div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.with_options\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.with_options\" class=\"fn\">with_options</a>(\n    backend: B,\n    options: TerminalOptions,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/1.96.1/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;Terminal&lt;B&gt;, &lt;B as Backend&gt;::Error&gt;</h4></section></summary><div class=\"docblock\"><p>Creates a new [<code>Terminal</code>] with the given [<code>Backend</code>] and [<code>TerminalOptions</code>].</p>\n<p>The viewport determines what area is exposed to widgets via <a href=\"crate::terminal::Frame::area\"><code>Frame::area</code></a> and how Ratatui\nkeeps its internal buffers synchronized with the backend. See [<code>Viewport</code>] for an overview\nof the available modes.</p>\n<p>For viewport behavior after initialization, see <a href=\"crate::terminal::Terminal::resize\"><code>Terminal::resize</code></a> and\n<a href=\"crate::terminal::Terminal::autoresize\"><code>Terminal::autoresize</code></a>.</p>\n<p>After creating a terminal, call [<code>Terminal::draw</code>] (or [<code>Terminal::try_draw</code>]) in a loop to\nrender your UI.</p>\n<p>Resize behavior depends on the selected viewport:</p>\n<ul>\n<li>[<code>Viewport::Fullscreen</code>] and [<code>Viewport::Inline</code>] are automatically resized during\n[<code>Terminal::draw</code>] / [<code>Terminal::try_draw</code>] (via <a href=\"crate::terminal::Terminal::autoresize\"><code>Terminal::autoresize</code></a>).</li>\n<li>[<code>Viewport::Fixed</code>] is not automatically resized; call <a href=\"crate::terminal::Terminal::resize\"><code>Terminal::resize</code></a> if the region\nshould change.</li>\n</ul>\n<h5 id=\"example-1\"><a class=\"doc-anchor\" href=\"#example-1\">§</a>Example</h5>\n<div class=\"example-wrap\"><pre class=\"rust rust-example-rendered\"><code><span class=\"kw\">use </span>std::io::stdout;\n\n<span class=\"kw\">use </span>ratatui::backend::CrosstermBackend;\n<span class=\"kw\">use </span>ratatui::layout::Rect;\n<span class=\"kw\">use </span>ratatui::{Terminal, TerminalOptions, Viewport};\n\n<span class=\"kw\">let </span>backend = CrosstermBackend::new(stdout());\n<span class=\"kw\">let </span>viewport = Viewport::Fixed(Rect::new(<span class=\"number\">0</span>, <span class=\"number\">0</span>, <span class=\"number\">10</span>, <span class=\"number\">10</span>));\n<span class=\"kw\">let </span>_terminal = Terminal::with_options(backend, TerminalOptions { viewport })<span class=\"question-mark\">?</span>;</code></pre></div>\n<p>When the viewport is [<code>Viewport::Inline</code>], Ratatui anchors the viewport to the current\ncursor row at initialization time (always starting at column 0). Ratatui may append lines\nand thereby scroll the terminal to make enough room for the requested height so the\nviewport stays fully visible.</p>\n</div></details></div></details>",0,"konnektoren_tui::tui::Tui"],["<details class=\"toggle implementors-toggle\" open><summary><section id=\"impl-Terminal%3CB%3E\" class=\"impl\"><a href=\"#impl-Terminal%3CB%3E\" class=\"anchor\">§</a><h3 class=\"code-header\">impl&lt;B&gt; Terminal&lt;B&gt;<div class=\"where\">where\n    B: Backend,</div></h3></section></summary><div class=\"impl-items\"><details class=\"toggle method-toggle\" open><summary><section id=\"method.resize\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.resize\" class=\"fn\">resize</a>(&amp;mut self, area: Rect) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/1.96.1/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/1.96.1/std/primitive.unit.html\">()</a>, &lt;B as Backend&gt;::Error&gt;</h4></section></summary><div class=\"docblock\"><p>Updates the Terminal so that internal buffers match the requested area.</p>\n<p>This updates the buffer size used for rendering and triggers a full clear so the next\n[<code>Terminal::draw</code>] / [<code>Terminal::try_draw</code>] paints into a consistent area.</p>\n<p>When the viewport is [<code>Viewport::Inline</code>], the <code>area</code> argument is treated as the new\nterminal size and the viewport origin is recomputed relative to the current cursor position.\nRatatui attempts to keep the cursor at the same relative row within the viewport across\nresizes.</p>\n<p>See also: [<code>Terminal::autoresize</code>] (automatic resizing during [<code>Terminal::draw</code>] /\n[<code>Terminal::try_draw</code>]).</p>\n<p>For [<code>Viewport::Fixed</code>] and [<code>Viewport::Fullscreen</code>], <code>area</code> becomes the new viewport area.\nFor [<code>Viewport::Inline</code>], <code>area</code> is interpreted as the backend’s new terminal size and the\nviewport origin may move to preserve the cursor’s relative row within the inline UI.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.autoresize\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.autoresize\" class=\"fn\">autoresize</a>(&amp;mut self) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/1.96.1/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/1.96.1/std/primitive.unit.html\">()</a>, &lt;B as Backend&gt;::Error&gt;</h4></section></summary><div class=\"docblock\"><p>Queries the backend for size and resizes if it doesn’t match the previous size.</p>\n<p>This is called automatically during [<code>Terminal::draw</code>] / [<code>Terminal::try_draw</code>] for\nfullscreen and inline viewports. Fixed viewports are not automatically resized.</p>\n<p>If the size changed, this calls [<code>Terminal::resize</code>] and therefore clears the affected\nregion before the next frame is rendered.</p>\n</div></details></div></details>",0,"konnektoren_tui::tui::Tui"],["<section id=\"impl-Eq-for-Terminal%3CB%3E\" class=\"impl\"><a href=\"#impl-Eq-for-Terminal%3CB%3E\" class=\"anchor\">§</a><h3 class=\"code-header\">impl&lt;B&gt; <a class=\"trait\" href=\"https://doc.rust-lang.org/1.96.1/core/cmp/trait.Eq.html\" title=\"trait core::cmp::Eq\">Eq</a> for Terminal&lt;B&gt;<div class=\"where\">where\n    B: <a class=\"trait\" href=\"https://doc.rust-lang.org/1.96.1/core/cmp/trait.Eq.html\" title=\"trait core::cmp::Eq\">Eq</a> + Backend,</div></h3></section>","Eq","konnektoren_tui::tui::Tui"],["<section id=\"impl-StructuralPartialEq-for-Terminal%3CB%3E\" class=\"impl\"><a href=\"#impl-StructuralPartialEq-for-Terminal%3CB%3E\" class=\"anchor\">§</a><h3 class=\"code-header\">impl&lt;B&gt; <a class=\"trait\" href=\"https://doc.rust-lang.org/1.96.1/core/marker/trait.StructuralPartialEq.html\" title=\"trait core::marker::StructuralPartialEq\">StructuralPartialEq</a> for Terminal&lt;B&gt;<div class=\"where\">where\n    B: Backend,</div></h3></section>","StructuralPartialEq","konnektoren_tui::tui::Tui"]]]]);
    if (window.register_type_impls) {
        window.register_type_impls(type_impls);
    } else {
        window.pending_type_impls = type_impls;
    }
})()
